-- Every member reads it: whether the company is registered for sales tax decides what every
-- document shows. Only the owner finishes the wizard, under their own name.
CREATE POLICY company_setup_select ON public.company_setup FOR SELECT TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()));
--> statement-breakpoint
CREATE POLICY company_setup_insert ON public.company_setup FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) = 'owner'
    AND completed_by = (SELECT app.current_user_id())
  );
